CREATE TABLE farms(`id` bigint  UNSIGNED PRIMARY KEY AUTO_INCREMENT,`created_at` timestamp  DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` timestamp  DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NOT NULL,`enable` TINYINT(1)  NOT NULL  DEFAULT 1 ,`name` varchar(255)  NOT NULL,`description` text  NULL,`location_state` varchar(100)  NOT NULL,`location_district` varchar(100)  NOT NULL,`location_block` varchar(100)  NULL,`location_village` varchar(100)  NULL,`latitude` DECIMAL(10,8)  NULL,`longitude` DECIMAL(11,8)  NULL,`total_area` DECIMAL(10,2)  NOT NULL,`cultivable_area` DECIMAL(10,2)  NULL,`area_unit` varchar(20)  NULL,`primary_soil_type` varchar(50)  NULL,`soil_ph` DECIMAL(3,1)  NULL,`soil_characteristics` jsonb  NULL,`irrigation_type` varchar(50)  NULL,`water_availability` varchar(50)  NULL,`previous_crops` text[]  NULL,`farming_experience_years` integer  NULL,`investment_capacity_per_acre` DECIMAL(10,2)  NULL,`farm_profile_embedding` vector(512)  NULL,`is_active` boolean  NULL DEFAULT true,`is_verified` boolean  NULL DEFAULT false)ENGINE = InnoDB AUTO_INCREMENT = 1 DEFAULT CHARSET = utf8;